import fs from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'lib/db.json');

export async function getPreference() {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data).notificationsEnabled;
  } catch (error) {
    return false;
  }
}

export async function togglePreference() {
  const current = await getPreference();
  const newData = { notificationsEnabled: !current };
  await fs.writeFile(DB_PATH, JSON.stringify(newData, null, 2));
  return newData.notificationsEnabled;
}

