'use server';

import { revalidatePath } from 'next/cache';
import { togglePreference } from '@/lib/db';

export async function toggleNotificationAction() {
  // Simulate checking for user (e.g., await getCurrentUser())
  // await new Promise((resolve) => setTimeout(resolve, 500)); // Simulate async work

  await togglePreference();

  // Revalidate the current path to update the UI with the new preference
  // This refreshes the data without a full page reload or redirect
  revalidatePath('/');
}

