import { getPreference } from '@/lib/db';
import { toggleNotifications } from './actions';

export default async function Home() {
  const notificationsEnabled = await getPreference();

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Notification Settings</h1>

      <div style={{ 
        border: '1px solid #ccc', 
        padding: '1.5rem', 
        borderRadius: '8px',
        maxWidth: '400px'
      }}>
        <p style={{ marginBottom: '1rem' }}>
          Current Status: 
          <strong style={{ 
            marginLeft: '0.5rem', 
            color: notificationsEnabled ? 'green' : 'red' 
          }}>
            {notificationsEnabled ? 'ENABLED' : 'DISABLED'}
          </strong>
        </p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            style={{
              padding: '0.75rem 1.5rem',
              backgroundColor: notificationsEnabled ? '#e53e3e' : '#3182ce',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '1rem',
              cursor: 'pointer',
              transition: 'background-color 0.2s'
            }}
          >
            {notificationsEnabled ? 'Disable Notifications' : 'Enable Notifications'}
          </button>
        </form>
      </div>

      <p style={{ marginTop: '2rem', fontSize: '0.9rem', color: '#666' }}>
        This toggle uses a Server Action with <code>revalidatePath('/')</code> to refresh the UI immediately without a full page reload or redirect.
      </p>
    </main>
  );
}

